/ Trusted only when fileSize still matches the fresh MEGA size.\n  mp4Faststart       Boolean?\n  thumbnail          String?\n  thumbnailAvailable Boolean                @default(false)\n  embedUrl           String?\n  sortOrder          Int                    @default(0)\n  tags               String?\n  createdAt          DateTime               @default(now())\n  updatedAt          DateTime               @updatedAt\n  /// Raw MEGA file-attribute list - used to detect new thumbnails/media attrs.\n  megaFa             String?\n  /// MEGA node timestamp (upload/modify time) - used for change detection.\n  megaModifiedAt     DateTime?\n  creator            Creator?               @relation(fields: [creatorId], references: [id])\n  megaAccount        MegaAccount?           @relation(fields: [megaAccountId], references: [id], onDelete: Cascade)\n  watchlistedBy      WatchlistItem[]\n  savedBy            SavedVideo[]\n  watchHistory       WatchHistory[]\n  previewJobs        PreviewGenerationJob[]\n\n  @@unique([megaAccountId, megaNodeId])\n  @@index([creatorId, createdAt])\n  @@index([sortOrder])\n  @@index([title])\n  @@index([megaAccountId, createdAt])\n}\n\nmodel User {\n  id                  String          @id @default(cuid())\n  email               String          @unique\n  passwordHash        String\n  /// Clerk user ID (e.g. \"user_...\") linking this MegaTube user to its\n  /// Clerk identity. Null for legacy password-only accounts until they\n  /// sign in through Clerk, at which point they are linked by email.\n  /// Never replaces the internal id - all user-owned data stays keyed\n  /// by the existing id.\n  clerkUserId         String?         @unique\n  createdAt           DateTime        @default(now())\n  updatedAt           DateTime        @updatedAt\n  megaAccounts        MegaAccount[]\n  sessions            Session[]\n  creators            Creator[]\n  watchlist           WatchlistItem[]\n  savedVideos         SavedVideo[]\n  savedFolders        SavedFolder[]\n  watchHistory        WatchHistory[]\n  /// Phase 5.1: non-blocking preview generation during MEGA sync (default on).\n  previewAutoGenerate Boolean         @default(true)\n  /// Phase 5.1: administrator pause for bulk preview generation. Existing\n  /// pending jobs stay durable and resume when this is cleared.\n  previewPaused       Boolean         @default(false)\n}\n\n/// Phase 5.1 durable preview-generation backlog.\n///\n/// One row per (video, hover preview, source fingerprint, generation\n/// version). The unique idempotency key makes sync/hover/manual enqueues\n/// safe to repeat: a duplicate insert is a no-op instead of a duplicate job.\n/// MEGA URLs, session material and file keys are never stored here.\nmodel PreviewGenerationJob {\n  id                Int       @id @default(autoincrement())\n  videoId           Int\n  kind              String    @default(\"hover\")\n  /// Identity of the source bytes: megaNodeId + fileSize.\n  sourceFingerprint String\n  /// Fingerprint of the encoding/scene-selection configuration.\n  generationVersion String\n  /// `${videoId}:${kind}:${sourceFingerprint}:${generationVersion}`\n  idempotencyKey    String    @unique\n  /// pending | queued | generating | completed | failed | unsupported\n  status            String    @default(\"pending\")\n  /// acquiring | scene-selection | encoding | publishing | null\n  stage             String?\n  priority          Int       @default(0)\n  /// Successful worker claims. Incremented even when the worker dies before\n  /// any generation work starts, so crash-only churn is visible separately\n  /// from real generation attempts.\n  claimCount        Int       @default(0)\n  /// Actual generation attempts. Incremented once, via\n  /// beginPreviewGenerationAttempt(), when a worker starts source acquisition\n  /// for a claimed job. A claim-then-crash can never consume this budget.\n  attempts          Int       @default(0)\n  maxAttempts       Int       @default(3)\n  /// Exp